def match_parens(lst):
    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    str1, str2 = lst
    open_count_str1 = str1.count('(')
    close_count_str1 = str1.count(')')
    open_count_str2 = str2.count('(')
    close_count_str2 = str2.count(')')

    if open_count_str1 != close_count_str1 or open_count_str2 != close_count_str2:
        return 'No'

    concatenated_str = str1 + str2

    if not is_balanced(concatenated_str):
        return 'No'

    return 'Yes'

